#define AUF_LANG_FRE
// Photo mode (auf::photo_mode, on foot; with several players from a player's pause): F10 stops the game and frees the camera: the mouse looks, W A S D
// move, Space and C go up and down, Shift faster, Ctrl slower; [ and ] the field of view, , and . the focus distance, N and
// M the blur, B depth of field on or off, R all as the game had them; the HUD, the menus and the gun are hidden, so F12
// (the screenshot key) takes the picture. F10 again leaves it: the game as it was.
//
// The game stays in its pause ([0x3B2428], set here when F10 came during play): the game step 0x293B0 is skipped
// then, and the pause menu's input and tick 0x33920 (cdecl, 2 arguments) are skipped here so nothing in it acts.
// The scene still draws while paused: 0x15E050 builds player 1's camera matrix and hands it to 0x15D5A0 (cdecl: the
// refdef 0x357B80, a 64-byte matrix), which makes from that one matrix the view, the culling frustum and the PVS, so
// the free camera is written into that matrix (when the view drawn [0x358780] is 0). Rows (D3D, row vectors, Z up,
// degrees; P pitch, positive down, Y yaw from +X anticlockwise): right (sin Y, -cos Y, 0), down (-sin P cos Y,
// -sin P sin Y, -cos P), back (-cos P cos Y, -cos P sin Y, sin P), the position. The HUD and the pause menu draw only
// with [0x3587FC] set, the first person gun with [0x3587C4]: both 0 meanwhile, put back after.
#include "bond/addr.h"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstring>

#ifdef _WIN32
#ifndef NOMINMAX
#define NOMINMAX
#endif
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
#else
constexpr int VK_F10 = 0x79, VK_SHIFT = 0x10, VK_CONTROL = 0x11, VK_SPACE = 0x20;
#endif

#include "app/app.h"
#include "common/auf.h"
#include "core/input.h"
#include "core/log.h"
#include "kernel/kernel.h"
#include "xdk/hle.h"

namespace {
constexpr uint32_t kPaused = A(0x3B2428), kRefdef = A(0x357B80), kViewDrawn = A(0x358780);
constexpr uint32_t kDraw2D = A(0x3587FC), kDrawGun = A(0x3587C4), kPlayers = A(0x205408);
constexpr uint32_t kPauseState = A(0x3B2200), kFrozen = A(0x3B2418);  // per player 16 bytes: 3 is the pause owner
constexpr float kPi = 3.14159265f, kSpeed = 220.0f, kTurn = 160.0f;  // units, degrees a second

struct Photo {
    bool on = false, paused_here = false, seeded = false;
    uint32_t owner = 0;  // the player whose pause it is (the view that flies)
    float fov = 1.0f;  // a factor on the game's field of view
    bool had_dof = false;
    uint32_t had_focus = 10, had_blur = 6;
    float x = 0, y = 0, z = 0, pitch = 0, yaw = 0;
    uint32_t draw_2d = 1, draw_gun = 1;
    std::chrono::steady_clock::time_point last{};
} g;

bool Key(int vk) {
#ifdef _WIN32
    return (GetAsyncKeyState(vk) & 0x8000) != 0 && GetForegroundWindow() == static_cast<HWND>(app::Window());
#else
    (void)vk;
    return false;
#endif
}

// with several players: the lowest whose pause menu is up ([0x3B2200 + 16 i] is 3), else -1
int PauseOwner() {
    for (uint32_t i = 0; i < std::min<uint32_t>(kernel::R32(kPlayers), 4); i++)
        if (kernel::R32(kPauseState + 16 * i) == 3) return int(i);
    return -1;
}

void Enter(uint32_t owner) {
    g.owner = owner;
    g.paused_here = kernel::R32(kPaused) == 0 && kernel::R32(kPlayers) == 1;  // several players: their own pause holds it
    if (g.paused_here) kernel::G<uint32_t>(kPaused) = 1;
    g.draw_2d = kernel::R32(kDraw2D), g.draw_gun = kernel::R32(kDrawGun);
    g.on = true, g.seeded = false, g.fov = 1.0f;
    app::Settings& st = app::Get();  // depth of field is the photo mode's own while it lasts: put back on leaving
    g.had_dof = st.depth_of_field, g.had_focus = st.focus_distance, g.had_blur = st.dof_blur;
    g.last = std::chrono::steady_clock::now();
    LOGR("auf: photo mode, player %u's view", owner + 1);
}

void Leave() {
    kernel::G<uint32_t>(kDraw2D) = g.draw_2d, kernel::G<uint32_t>(kDrawGun) = g.draw_gun;
    if (g.paused_here) kernel::G<uint32_t>(kPaused) = 0;
    app::Settings& st = app::Get();
    st.depth_of_field = g.had_dof, st.focus_distance = g.had_focus, st.dof_blur = g.had_blur;
    g.on = false;
    float x, y;
    input::TakeMouse(x, y);  // what moved meanwhile is not the game's
    LOGR("auf: photo mode left");
}

// F10, once a press. One player: on foot, pausing as it starts. Several: from a player's own pause (the controller's
// Start), the view of the lowest pause owner flying
void Toggle() {
    static bool was = false;
    const bool down = Key(auf::KeyOf(auf::photo_key));
    const bool several = kernel::R32(kPlayers) > 1;
    if (down && !was) {
        if (g.on) Leave();
        else if (auf::photo_mode && !app::OverlayOpen() && kernel::R32(kFrozen) == 0) {
            if (!several && (auf::PlayerFree() || kernel::R32(kPaused))) Enter(0);
            else if (several && kernel::R32(kPaused) && PauseOwner() >= 0) Enter(uint32_t(PauseOwner()));
        }
    }
    // it ends with the pause it was taken in: a player's menu closed, or the game frozen or ending
    if (g.on && several && (PauseOwner() < 0 || kernel::R32(kFrozen) != 0)) Leave();
    was = down;
}

// the picture's own controls, one press at a time (held keys repeat at the frame rate): [ ] the field of view, , . the
// focus distance, N M the blur, B depth of field on and off, R all as the game had them
void Controls(float dt) {
    app::Settings& st = app::Get();
    static bool was_b = false, was_r = false;
    const float fov_rate = 0.6f * dt;
    if (Key(0xDB)) g.fov = std::clamp(g.fov - fov_rate, 0.3f, 2.0f);  // [ narrower
    if (Key(0xDD)) g.fov = std::clamp(g.fov + fov_rate, 0.3f, 2.0f);  // ] wider
    static float focus = 0, blur = 0;
    focus = std::clamp(float(st.focus_distance) + (Key(0xBE) - Key(0xBC)) * 30.0f * dt, 1.0f, 100.0f);  // , nearer . further
    if (Key(0xBC) || Key(0xBE)) st.focus_distance = uint32_t(focus + 0.5f);
    blur = std::clamp(float(st.dof_blur) + (Key('M') - Key('N')) * 6.0f * dt, 0.0f, 12.0f);  // N less M more
    if (Key('N') || Key('M')) st.dof_blur = uint32_t(blur + 0.5f);
    const bool b = Key('B'), r = Key('R');
    if (b && !was_b) {
        st.depth_of_field = !st.depth_of_field;
        LOGR("auf: photo mode: depth of field %s", st.depth_of_field ? "on" : "off");
    }
    if (r && !was_r) {
        g.fov = 1.0f;
        st.depth_of_field = g.had_dof, st.focus_distance = g.had_focus, st.dof_blur = g.had_blur;
        LOGR("auf: photo mode: field of view, depth of field as the game had them");
    }
    was_b = b, was_r = r;
}

void Fly(uint32_t m) {
    float* f = reinterpret_cast<float*>(&kernel::G<uint32_t>(m));
    if (!g.seeded) {  // from where the game's camera is
        g.pitch = std::asin(std::clamp(f[10], -1.0f, 1.0f)) * 180 / kPi;
        g.yaw = std::atan2(-f[9], -f[8]) * 180 / kPi;
        g.x = f[12], g.y = f[13], g.z = f[14];
        g.seeded = true;
    }
    const auto now = std::chrono::steady_clock::now();
    const float dt = std::clamp(std::chrono::duration<float>(now - g.last).count(), 0.0f, 0.1f);
    g.last = now;
    Controls(dt);
    float mx = 0, my = 0;
    if (input::TakeMouse(mx, my)) {
        g.yaw -= mx * kTurn * dt;
        g.pitch = std::clamp(g.pitch - my * kTurn * dt, -89.0f, 89.0f);
    }
    const float P = g.pitch * kPi / 180, Y = g.yaw * kPi / 180;
    const float sp = std::sin(P), cp = std::cos(P), sy = std::sin(Y), cy = std::cos(Y);
    const float fwd[3] = {cp * cy, cp * sy, -sp}, right[3] = {sy, -cy, 0};
    float speed = kSpeed * dt * (Key(VK_SHIFT) ? 3.0f : 1.0f) * (Key(VK_CONTROL) ? 0.25f : 1.0f);
    float mf = float(Key('W')) - float(Key('S')), mr = float(Key('D')) - float(Key('A')), mu = float(Key(VK_SPACE)) - float(Key('C'));
    g.x += (fwd[0] * mf + right[0] * mr) * speed;
    g.y += (fwd[1] * mf + right[1] * mr) * speed;
    g.z += (fwd[2] * mf + mu) * speed;
    const float rows[16] = {sy, -cy, 0, 0, -sp * cy, -sp * sy, -cp, 0, -cp * cy, -cp * sy, sp, 0, g.x, g.y, g.z, 1};
    std::memcpy(f, rows, sizeof rows);
}
}  // namespace

// the camera matrix the view, culling and PVS are made from
X86_EXTERN_FUNC(__imp__sub_0015D4B0);
X86_FUNC(sub_0015D4B0) {
    if (kernel::R32(ctx.esp + 4) == kRefdef) {
        const uint32_t view = kernel::R32(kViewDrawn);
        if (view == 0) Toggle();  // once a frame, with the first view
        if (g.on && !auf::photo_mode) Leave();
        if (g.on) {
            if (view != g.owner) {  // the other views draw as the game has them
                kernel::G<uint32_t>(kDraw2D) = g.draw_2d, kernel::G<uint32_t>(kDrawGun) = g.draw_gun;
            } else {
                kernel::G<uint32_t>(kDraw2D) = 0, kernel::G<uint32_t>(kDrawGun) = 0;
                Fly(kernel::R32(ctx.esp + 8));
                float& fov = *reinterpret_cast<float*>(&kernel::G<uint32_t>(kRefdef + 0x2D4));  // radians, set before this call
                fov = std::clamp(fov * g.fov, 0.15f, 2.7f);
            }
        }
    }
    __imp__sub_0015D4B0(ctx, base);
}

